<?php
declare(strict_types=1);
const TRANSFER_BLOBS=['events'=>'photo_jpeg','task_recipients'=>'proof_jpeg'];
function business_tables(): array {return array_values(array_diff(array_keys(schema()),['sessions','meta','login_attempts','telegram_link_codes','sheet_sync_nonces']));}
function envelope(array $tables): string {$payload=json_encode(['format'=>'anhgau-transfer-v1','tables'=>$tables,'exported_at'=>now_ms()],JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);return gzencode(json_encode(['format'=>'anhgau-envelope-v1','sha256'=>hash('sha256',$payload),'payload'=>base64_encode($payload)],JSON_THROW_ON_ERROR),6);}
function read_transfer(string $bytes): array {if(strlen($bytes)>32000000)fail('Tệp chuyển dữ liệu vượt 32 MB. Cần chuyển bằng CLI.');$raw=@gzdecode($bytes,128000000);if($raw===false)fail('Tệp không đúng định dạng .json.gz.');$e=json_decode($raw,true,64,JSON_THROW_ON_ERROR);if(($e['format']??'')!=='anhgau-envelope-v1')fail('Tệp không đúng định dạng chuyển dữ liệu.');$payload=base64_decode($e['payload']??'',true);if($payload===false||!hash_equals(hash('sha256',$payload),$e['sha256']??''))fail('Tệp hỏng, không vượt qua kiểm tra SHA-256.');$p=json_decode($payload,true,64,JSON_THROW_ON_ERROR);if(($p['format']??'')!=='anhgau-transfer-v1'||!is_array($p['tables']??null)||empty($p['tables']['users']))fail('Thiếu dữ liệu người dùng.');return $p['tables'];}
function export_tables(App $a): array {$tables=[];foreach(business_tables() as $table){$tables[$table]=$a->all('SELECT * FROM {{'.$table.'}}');if(isset(TRANSFER_BLOBS[$table]))foreach($tables[$table] as &$row)if($row[TRANSFER_BLOBS[$table]]!==null)$row[TRANSFER_BLOBS[$table]]=base64_encode($row[TRANSFER_BLOBS[$table]]);unset($row);}return $tables;}
function backup_list(App $a): array {$files=[];foreach(glob($a->storage.'/backups/studio-*.json.gz') as $file){$name=basename($file);if(preg_match('/^studio-(\d{13})-[a-f0-9]+\.json\.gz$/D',$name,$m))$files[]=['name'=>$name,'time'=>(int)$m[1],'size'=>filesize($file)];}usort($files,fn($x,$y)=>$y['time']<=>$x['time']);return $files;}
function create_backup(App $a): array {return $a->tx(function()use($a){$photoBytes=(int)$a->scalar('SELECT COALESCE(SUM(OCTET_LENGTH(photo_jpeg)),0) FROM {{events}}')+(int)$a->scalar('SELECT COALESCE(SUM(OCTET_LENGTH(proof_jpeg)),0) FROM {{task_recipients}}');$rowCount=0;foreach(business_tables() as $t)$rowCount+=(int)$a->scalar('SELECT COUNT(*) FROM {{'.$t.'}}');if($photoBytes>8000000||$rowCount>20000)fail('Dữ liệu vượt mức sao lưu PHP trong shared hosting. Hãy sao lưu database riêng và thư mục nhansu-private bằng Hostinger hPanel; dữ liệu hiện tại vẫn được giữ nguyên.',409);$bytes=envelope(export_tables($a));read_transfer($bytes);$name='studio-'.now_ms().'-'.bin2hex(random_bytes(4)).'.json.gz';$temp=$a->storage.'/backups/'.$name.'.tmp';if(file_put_contents($temp,$bytes,LOCK_EX)===false||!rename($temp,$a->storage.'/backups/'.$name))fail('Không ghi được bản sao lưu.',500);foreach(array_slice(backup_list($a),14) as $f)unlink($a->storage.'/backups/'.$f['name']);return ['name'=>$name,'time'=>now_ms()];});}
function import_tables(App $a,array $tables,string $email,string $password): array {
 if($a->scalar('SELECT COUNT(*) FROM {{users}}')>1||$a->scalar('SELECT COUNT(*) FROM {{events}}')||$a->scalar('SELECT COUNT(*) FROM {{shift_assignments}}')||$a->scalar('SELECT COUNT(*) FROM {{commissions}}'))fail('Chỉ nhập vào bản cài mới, chưa thêm nhân viên hay chấm công. Dữ liệu hiện tại được giữ nguyên.',409);
 if(strlen($password)<10||strlen($password)>128)fail('Mật khẩu Admin mới cần 10–128 ký tự.');$email=strtolower(trim($email));$admin=null;$ids=[];$emails=[];
 foreach($tables['users'] as $u){if(!is_int($u['id']??null)||$u['id']<1||!in_array($u['role']??'', ['admin','manager','employee'],true)||!filter_var($u['email']??'',FILTER_VALIDATE_EMAIL)||empty($u['name'])||empty($u['password']))fail('Dữ liệu nhân viên không hợp lệ.');$lower=strtolower($u['email']);if(isset($ids[$u['id']])||isset($emails[$lower]))fail('Trùng mã hoặc email nhân viên.');$ids[$u['id']]=true;$emails[$lower]=true;if($lower===$email&&$u['role']==='admin'&&!($u['archived']??0)&&($u['status']??'active')!=='inactive')$admin=$u['id'];}
 if(!$admin)fail('Email phải thuộc Admin đang hoạt động trong dữ liệu cũ.');
 foreach(['events','salaries','commissions','attendance_requests','shift_assignments','telegram_links','telegram_schedules','telegram_deliveries','salary_advances','event_log_recorders','task_recipients'] as $t)foreach($tables[$t]??[] as $r)if(!isset($ids[$r['user_id']??0]))fail('Dữ liệu tham chiếu nhân viên không tồn tại: '.$t);
 foreach(business_tables() as $t)$a->run('DELETE FROM {{'.$t.'}}');$a->run('DELETE FROM {{sessions}}');$a->run('DELETE FROM {{telegram_link_codes}}');
 $counts=[];foreach(business_tables() as $t){$columns=array_column($a->all('SHOW COLUMNS FROM {{'.$t.'}}'),'Field');$counts[$t]=0;foreach($tables[$t]??[] as $r){$r=array_intersect_key($r,array_flip($columns));if($t==='users'){$r['email']=strtolower($r['email']);$r['employee_code']=$r['employee_code']?:'NV'.str_pad((string)$r['id'],4,'0',STR_PAD_LEFT);$r['notes']=$r['notes']??'';if($r['id']===$admin)$r['password']=password_hash($password,PASSWORD_DEFAULT);}if($t==='events'){$r['reason']=$r['reason']??'';if(!empty($r['photo_jpeg'])){$photo=base64_decode($r['photo_jpeg'],true);if($photo===false||strlen($photo)>1000000||!@getimagesizefromstring($photo))fail('Ảnh chấm công trong tệp không hợp lệ.');$r['photo_jpeg']=$photo;}}if($t==='task_recipients'&&!empty($r['proof_jpeg'])){$photo=base64_decode($r['proof_jpeg'],true);if($photo===false||strlen($photo)>1000000||!@getimagesizefromstring($photo))fail('Ảnh bằng chứng trong tệp không hợp lệ.');$r['proof_jpeg']=$photo;}if(!$r)fail('Dòng dữ liệu trống.');$keys=array_keys($r);$a->run('INSERT INTO {{'.$t.'}} (`'.implode('`,`',$keys).'`) VALUES('.implode(',',array_fill(0,count($r),'?')).')',array_values($r));$counts[$t]++;}}
 $a->meta('telegram_offset','0');$a->meta('telegram_identity','null');$a->meta('telegram_bot_id','');$a->meta('telegram_fingerprint','');$a->meta('telegram_error','');$a->cookie('',time()-3600);return $counts;
}
function transfer_routes(App $a,string $path,array $b,string $method): ?array {
 if($path==='/migration/status'&&$method==='GET'){$a->requireAdmin();return [200,['users'=>(int)$a->scalar('SELECT COUNT(*) FROM {{users}}'),'events'=>(int)$a->scalar('SELECT COUNT(*) FROM {{events}}'),'runtime'=>'PHP '.PHP_VERSION,'database'=>'MySQL','base'=>$a->base]];}
 if($path==='/migration/import'&&$method==='POST'){$a->requireAdmin();if(!is_string($b['password']??null)||!password_verify($b['password'],$a->user['password']))fail('Mật khẩu Admin đang đăng nhập không đúng.',403);$file=$_FILES['file']??null;if(!$file||$file['error']!==UPLOAD_ERR_OK||!is_uploaded_file($file['tmp_name']))fail('Tệp chưa tải lên được. Kiểm tra giới hạn upload của PHP.');$tables=read_transfer(file_get_contents($file['tmp_name']));$counts=import_tables($a,$tables,$b['admin_email']??'',$b['new_password']??'');return [200,['ok'=>true,'counts'=>$counts]];}
 if($path==='/backups'&&$method==='GET'){$a->requireAdmin();return [200,['files'=>backup_list($a),'keep'=>14,'lastError'=>$a->meta('backup_error')??'']];}
 if($path==='/backups'&&$method==='POST'){$a->requireAdmin();return [201,create_backup($a)];}
 if(preg_match('~^/backups/(studio-\d{13}-[a-f0-9]+\.json\.gz)$~D',$path,$m)&&$method==='GET'){$a->requireAdmin();$file=$a->storage.'/backups/'.$m[1];if(!is_file($file))fail('Không tìm thấy bản sao lưu.',404);header('Content-Type: application/gzip');header('Content-Disposition: attachment; filename="'.$m[1].'"');readfile($file);exit;}
 return null;
}
